BEGIN;
CREATE FUNCTION pg_temp.m5_ok(v boolean, message text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF v IS DISTINCT FROM true THEN RAISE EXCEPTION 'M4B_ASSERT: M5 %',message; END IF; END $$;
CREATE FUNCTION pg_temp.m5_denied(query text, code text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN
 BEGIN EXECUTE query; EXCEPTION WHEN OTHERS THEN IF SQLSTATE=code THEN RETURN; ELSE RAISE; END IF; END;
 RAISE EXCEPTION 'M4B_ASSERT: M5 expected denial %',query;
END $$;
GRANT EXECUTE ON FUNCTION pg_temp.m5_ok(boolean,text),pg_temp.m5_denied(text,text) TO authenticated;
INSERT INTO auth.users(id) VALUES ('61000000-0000-0000-0000-000000000001'),('61000000-0000-0000-0000-000000000002');
INSERT INTO public.contests(id,owner_id,course,protocol,sync_enabled,invite_code) VALUES('62000000-0000-0000-0000-000000000001','61000000-0000-0000-0000-000000000001','{"holes":[{"num":1,"par":4}]}',1,true,'M5BUDG');
SELECT pg_temp.m5_ok(NOT has_table_privilege('authenticated','public.sync_join_budgets','SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER') AND NOT has_table_privilege('anon','public.sync_join_budgets','SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER'),'budgets private');
SELECT pg_temp.m5_ok(has_function_privilege('authenticated','public.submit_group(uuid,uuid,uuid,bigint)','EXECUTE') AND has_function_privilege('authenticated','public.finalize_tournament(uuid,bigint)','EXECUTE'),'completion API grants');
SELECT pg_temp.m5_ok(NOT has_function_privilege('anon','public.submit_group(uuid,uuid,uuid,bigint)','EXECUTE') AND NOT has_function_privilege('anon','public.finalize_tournament(uuid,bigint)','EXECUTE'),'anonymous role cannot complete');
SET LOCAL ROLE authenticated;
SET LOCAL request.jwt.claims='{"sub":"61000000-0000-0000-0000-000000000002","is_anonymous":true,"role":"authenticated"}';
SELECT pg_temp.m5_ok(public.request_join('UNKNOWN','Guest')='{"status":"pending"}'::jsonb,'unknown code generic');
RESET ROLE;
INSERT INTO public.sync_join_budgets VALUES('actor:61000000-0000-0000-0000-000000000002',date_trunc('minute',clock_timestamp()),5) ON CONFLICT(scope) DO UPDATE SET attempts=5,window_start=excluded.window_start;
SET LOCAL ROLE authenticated;
SELECT pg_temp.m5_ok(public.request_join('M5BUDG','Guest')='{"status":"pending"}'::jsonb,'identity cap generic');
RESET ROLE;
SELECT pg_temp.m5_ok(NOT EXISTS(SELECT 1 FROM public.contest_join_requests WHERE contest_id='62000000-0000-0000-0000-000000000001'),'identity cap blocks request');
UPDATE public.sync_join_budgets SET window_start=clock_timestamp()-interval '2 minutes';
INSERT INTO public.sync_join_budgets VALUES('event:62000000-0000-0000-0000-000000000001',date_trunc('minute',clock_timestamp()),60) ON CONFLICT(scope) DO UPDATE SET attempts=60,window_start=excluded.window_start;
SET LOCAL ROLE authenticated;
SELECT pg_temp.m5_ok(public.request_join('M5BUDG','Guest')='{"status":"pending"}'::jsonb,'event cap generic');
RESET ROLE;
SELECT pg_temp.m5_ok(NOT EXISTS(SELECT 1 FROM public.contest_join_requests WHERE contest_id='62000000-0000-0000-0000-000000000001'),'event cap blocks request');
UPDATE public.sync_join_budgets SET window_start=clock_timestamp()-interval '2 minutes';
UPDATE public.sync_join_budgets SET window_start=date_trunc('minute',clock_timestamp()),attempts=300 WHERE scope='global';
SET LOCAL ROLE authenticated;
SELECT pg_temp.m5_ok(public.request_join('M5BUDG','Guest')='{"status":"pending"}'::jsonb AND public.request_join('UNKNOWN','Guest')='{"status":"pending"}'::jsonb,'shared cap identical for real and nonexistent codes');
RESET ROLE;
SELECT pg_temp.m5_ok(NOT EXISTS(SELECT 1 FROM public.contest_join_requests WHERE contest_id='62000000-0000-0000-0000-000000000001'),'shared budget covers fresh identities');
UPDATE public.sync_join_budgets SET window_start=clock_timestamp()-interval '2 minutes';
SET LOCAL ROLE authenticated;
SELECT public.request_join('M5BUDG','Guest');
RESET ROLE;
SELECT pg_temp.m5_ok(EXISTS(SELECT 1 FROM public.contest_join_requests WHERE contest_id='62000000-0000-0000-0000-000000000001'),'new window recovers');
INSERT INTO public.contest_players(id,contest_id,name) VALUES('63000000-0000-0000-0000-000000000001','62000000-0000-0000-0000-000000000001','Budget');
INSERT INTO public.operation_receipts(actor,op_id,request_hash,contest_id,result) SELECT '61000000-0000-0000-0000-000000000001',gen_random_uuid(),'budget','62000000-0000-0000-0000-000000000001','{}' FROM generate_series(1,120);
SET LOCAL ROLE authenticated;
SET LOCAL request.jwt.claims='{"sub":"61000000-0000-0000-0000-000000000001","is_anonymous":false,"role":"authenticated"}';
SELECT pg_temp.m5_denied($q$SELECT public.write_score('62000000-0000-0000-0000-000000000001',NULL,'63000000-0000-0000-0000-000000000001',1,'set',4,0,gen_random_uuid(),'budget')$q$,'54000');
UPDATE public.contests SET status='completed' WHERE id='62000000-0000-0000-0000-000000000001';
RESET ROLE;
SELECT pg_temp.m5_ok((SELECT status='active' FROM public.contests WHERE id='62000000-0000-0000-0000-000000000001'),'direct finalization has no effect');
SELECT pg_temp.m5_ok(NOT EXISTS(SELECT 1 FROM public.score_events WHERE contest_id='62000000-0000-0000-0000-000000000001'),'rate denial appends no score');
ROLLBACK;
